    faq: {
      title: "",
      highlight: "Enlarged Pores",
      titleSuffix: "Common Questions",
      description: "Answers to common questions about pore refinement treatments.",
      items: [
        {
          question: "Can pores actually be shrunk?",
          answer: "Pores cannot be erased (we need them!), but they can be significantly tightened by strengthening the collagen around them, making them look much smaller."
        },
        {
          question: "Will these treatments cause breakouts?",
          answer: "No. In fact, treatments like BioRePeel and Microneedling can help clear congestion and prevent future breakouts by keeping the pores clean."
        },
        {
          question: "Is there downtime?",
          answer: "Microneedling may cause 24–48 hours of redness, while peels like BioRePeel have zero social downtime."
        },
        {
          question: "Why do my pores look bigger as I age?",
          answer: "As we lose collagen, the skin loses elasticity and 'sags', causing the pore opening to stretch. Sun damage also degrades the collagen structure around the pore."
        },
        {
          question: "Can I just use a pore strip?",
          answer: "Pore strips only remove surface debris and often irritate the skin. They don't shrink the pore or prevent it from filling up again."
        },
        {
          question: "Does make-up clog pores?",
          answer: "Heavy, oil-based makeup can clog pores. We recommend mineral-based or non-comedogenic makeup, especially after treatment."
        },
        {
          question: "How many treatments will I need?",
          answer: "For visible pore reduction, a course of 3-6 microneedling or peel sessions is widely recommended to build enough collagen to tighten the structure."
        },
        {
          question: "Is it suitable for oily skin?",
          answer: "Yes. In fact, these treatments often help to regulate oil production as well as refining texture."
        },
        {
          question: "Can men treat enlarged pores?",
          answer: "Absolutely. Many of our male clients choose microneedling and BioRePeel for clearer, smoother skin."
        },
        {
          question: "What skincare should I use at home?",
          answer: "We recommend a simple routine including a gentle cleanser, a chemical exfoliant (like Salicylic Acid or PHformula) used sparingly, and SPF daily."
        },
        {
          question: "Will it hurt?",
          answer: "Microneedling is performed with numbing cream so it is comfortable. BioRePeel tingles but is not painful."
        }
      ]
    },
